	if getgenv().CoolwipHub_Cleanup then
		pcall(getgenv().CoolwipHub_Cleanup)
	end
end

getgenv().CoolwipHub_Executed = true

local fn = cloneref or function(...)
	return ...
end

local obj = setmetatable({}, { __index = function(arg, arg2)
	local ok, result = pcall(function()
		return fn(game:GetService(arg2))
	end)

	if ok then
