local function fn2(arg)
	if not arg or not arg.Character then
		return false
	end
	local humanoid = arg.Character:FindFirstChild("Humanoid")
	local humanoidRootPart = arg.Character:FindFirstChild("HumanoidRootPart")
	return humanoid and humanoidRootPart and humanoid.Health > 0
end

getgenv().CoolwipHub_Connections = getgenv().CoolwipHub_Connections or {}

for _, coolwipHubConnection in ipairs(getgenv().CoolwipHub_Connections) do
	if typeof(coolwipHubConnection) == "RBXScriptConnection" and coolwipHubConnection.Connected then
		pcall(function()
			coolwipHubConnection:Disconnect()
		end)
	end
end

table.clear(getgenv().CoolwipHub_Connections)

local function fn3(arg)
	if typeof(arg) == "RBXScriptConnection" then
		table.insert(getgenv().CoolwipHub_Connections, arg)
		return arg
	end
end

local function fn4(arg)
	if not arg then
		return
	end

	for i, coolwipHubConnection in ipairs(getgenv().CoolwipHub_Connections) do
		if coolwipHubConnection == arg then
			table.remove(getgenv().CoolwipHub_Connections, i)
			break
		end
	end

	if typeof(arg) == "RBXScriptConnection" and arg.Connected then
		arg:Disconnect()
	end
end

