	-- Original logo embedded as PNG data: no remote image request needed.
	local function loadCoolwipLogo()
		local assetLoader = getcustomasset or getsynasset
		if type(writefile) ~= "function" or type(assetLoader) ~= "function" then
			warn("Coolwip Hub: embedded logo needs writefile and getcustomasset/getsynasset; using Roblox thumbnail fallback.")
			return "rbxthumb://type=Asset&id=133516718930078&w=420&h=420"
		end
		local encoded = [=[]=]
		local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
		local lookup = {}
		for i = 1, #alphabet do lookup[string.byte(alphabet, i)] = i - 1 end
		local decoded = {}
		for i = 1, #encoded, 4 do
			local a, b, c, d = string.byte(encoded, i, i + 3)
			local n = lookup[a] * 262144 + lookup[b] * 4096 + (lookup[c] or 0) * 64 + (lookup[d] or 0)
			local chunk = string.char(math.floor(n / 65536) % 256, math.floor(n / 256) % 256, n % 256)
			decoded[#decoded + 1] = c == 61 and chunk:sub(1, 1) or d == 61 and chunk:sub(1, 2) or chunk
		end
		local success, content = pcall(function()
			local filename = "CoolwipHubLogoRefined.png"
			writefile(filename, table.concat(decoded))
			return assetLoader(filename)
		end)
		if success and type(content) == "string" and #content > 0 then return content end
		warn("Coolwip Hub: local logo loading failed: " .. tostring(content))
		return "rbxthumb://type=Asset&id=133516718930078&w=420&h=420"
	end
