			table.clear(taggedParts)
			taggedMap = nil
		end
		function aim.UpdatePassthrough()
			local map = (settings.GunMethod == "WallBang" or settings.KnifeMethod == "WallBang") and fn8() or nil
			if map == taggedMap then return end
			clearTags()
			if not map then return end
			taggedMap = map
